var ids=['signin','new-conversation','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];doc.pages.filter(p=>/^Proto macOS (Light|Dark)$/.test(p.name)).forEach(p=>p.layers.filter(s=>s.name.indexOf('Screen/macos/')===0&&ids.indexOf(s.name.split('/').pop())>=0).forEach(s=>{var links=[];function walk(l){if(l.name.indexOf('link:')===0)links.push(l.name);(l.layers||[]).forEach(walk);}walk(s);H.out({page:p.name,id:s.name.split('/').pop(),frame:String(s.id),x:s.frame.x,y:s.frame.y,w:s.frame.width,h:s.frame.height,links:Array.from(new Set(links)).sort()});}));